export const getAcceptInvitationUrl = (token: string) => {
  return `/api/invitations/${token}/accept`;
};

/**
 * 招待先のメールアドレスと、ログイン中のGoogleアカウントのメールアドレスが一致する場合だけ参加できる。一致しなければ403。
 * 受諾済みの同じ招待を同じユーザーが再度受諾しても、Membershipは重複せず成功する。
 * 取り消された・期限切れの招待は422で、detailsに理由を返す。
 * @summary 招待を受諾してWorkspaceに参加する
 */
export const acceptInvitation = async (
  token: string,
  options?: Parameters<typeof customFetch>[1],
): Promise<acceptInvitationResponseSuccess> => {
  return customFetch<acceptInvitationResponseSuccess>(getAcceptInvitationUrl(token), {
    ...options,
    method: "POST",
  });
};

export const getAcceptInvitationMutationKey = () => ["acceptInvitation"] as const;

export const getAcceptInvitationMutationOptions = <
  TError = ErrorType<
    | UnauthorizedResponse
    | ForbiddenResponse
    | NotFoundResponse
    | ValidationFailedResponse
    | InternalErrorResponse
  >,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof acceptInvitation>>,
    TError,
    AcceptInvitationMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof acceptInvitation>>,
  TError,
  AcceptInvitationMutationVariables,
  TContext
> => {
  const mutationKey = getAcceptInvitationMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof acceptInvitation>>,
    AcceptInvitationMutationVariables
  > = (props) => {
    const { token } = props ?? {};

    return acceptInvitation(token, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

